'use client';

import { useEffect, useId, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import './article-rail.css';

export interface ArticleRailItem {
  id: string;
  title: string;
  category: string;
  href: string;
  readTime?: string;
  date?: string;
  /** Decorative article artwork without nested controls. */
  media: ReactNode;
}

export interface ArticleRailProps {
  items: ArticleRailItem[];
  title?: string;
  className?: string;
}

/** A touch-scrollable journal rail with ordinary article links and bounded paging controls. */
export function ArticleRail({ items, title = 'Ideas worth sharing', className = '' }: ArticleRailProps) {
  const instance = useId();
  const viewport = useRef<HTMLDivElement>(null);
  const track = useRef<HTMLUListElement>(null);
  const [edges, setEdges] = useState({ start: true, end: items.length < 2 });

  useEffect(() => {
    const element = viewport.current;
    if (!element) return;
    let frame = 0;
    function measure() {
      if (!element) return;
      const maximum = Math.max(0, element.scrollWidth - element.clientWidth);
      const position = Math.max(0, element.scrollLeft);
      // Scroll snapping aligns the first card after the viewport's focus-ring inset.
      const startInset = Number.parseFloat(getComputedStyle(element).paddingLeft) || 0;
      const next = { start: position <= startInset + 2, end: position >= maximum - 2 };
      setEdges(previous => previous.start === next.start && previous.end === next.end ? previous : next);
    }
    function scheduleMeasure() {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(measure);
    }
    const observer = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(scheduleMeasure);
    observer?.observe(element);
    if (track.current) observer?.observe(track.current);
    element.addEventListener('scroll', scheduleMeasure, { passive: true });
    window.addEventListener('resize', scheduleMeasure);
    measure();
    return () => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
      element.removeEventListener('scroll', scheduleMeasure);
      window.removeEventListener('resize', scheduleMeasure);
    };
  }, [items.length]);

  function move(direction: -1 | 1) {
    const element = viewport.current;
    const cards = track.current?.children;
    if (!element || !cards?.length) return;
    const first = cards[0] as HTMLElement;
    const second = cards[1] as HTMLElement | undefined;
    const step = second ? second.offsetLeft - first.offsetLeft : first.offsetWidth;
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    element.scrollBy({ left: direction * step, behavior: reducedMotion ? 'auto' : 'smooth' });
  }

  if (!items.length) return null;

  return <section className={`ac-article-rail ${className}`.trim()} aria-labelledby={`${instance}-heading`}>
    <header className="ac-article-rail-header"><div><span className="ac-article-rail-eyebrow">THE JOURNAL</span><h2 id={`${instance}-heading`}>{title}</h2></div><div className="ac-article-rail-controls"><button type="button" aria-label="Previous articles" aria-controls={`${instance}-viewport`} disabled={edges.start} onClick={() => move(-1)}><span aria-hidden="true">←</span></button><button type="button" aria-label="Next articles" aria-controls={`${instance}-viewport`} disabled={edges.end} onClick={() => move(1)}><span aria-hidden="true">→</span></button></div></header>
    <div className="ac-article-rail-viewport" ref={viewport} id={`${instance}-viewport`}>
      <ul className="ac-article-rail-track" ref={track}>{items.map((item, index) => <li className="ac-article-rail-item" key={item.id}><article><a className="ac-article-rail-link" href={item.href} aria-labelledby={`${instance}-article-${index}`} aria-describedby={`${instance}-meta-${index}`}><div className="ac-article-rail-media" aria-hidden="true" ref={node => { if (node) node.setAttribute('inert', ''); }}>{item.media}<span className="ac-article-rail-link-arrow" aria-hidden="true">↗</span></div><div className="ac-article-rail-meta" id={`${instance}-meta-${index}`}><span>{item.category}</span><span>{[item.date, item.readTime].filter(Boolean).join(' · ')}</span></div><h3 id={`${instance}-article-${index}`}><span>{item.title}</span></h3></a></article></li>)}</ul>
    </div>
  </section>;
}

.ac-article-rail{--ac-article-surface:var(--ac-article-theme-surface, #f5f1e9);--ac-article-ink:var(--ac-article-theme-ink, #27271f);--ac-article-muted:var(--ac-article-theme-muted, #75766a);--ac-article-line:var(--ac-article-theme-line, #27271f30);--ac-article-accent:#ae4b30;box-sizing:border-box;container-type:inline-size;width:100%;padding:clamp(20px,4.5cqw,44px);background:var(--ac-article-surface);color:var(--ac-article-ink)}.ac-article-rail *{box-sizing:border-box}.ac-article-rail-header{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:25px}.ac-article-rail-eyebrow{font-size:9px;letter-spacing:.15em;font-weight:600}.ac-article-rail-header h2{margin:11px 0 0;font-size:clamp(26px,5.2cqw,43px);font-weight:500;letter-spacing:-.055em;line-height:1.05}.ac-article-rail-controls{display:flex;gap:7px;flex:0 0 auto;padding-bottom:2px}.ac-article-rail-controls button{appearance:none;display:grid;place-items:center;flex:0 0 auto;width:44px;height:44px;padding:0;border:1px solid var(--ac-article-line);border-radius:50%;background:transparent;color:var(--ac-article-ink);font:inherit;font-size:20px;line-height:1;cursor:pointer;transition:background .2s,color .2s,opacity .2s}.ac-article-rail-controls button:hover:not(:disabled){background:var(--ac-article-ink);color:var(--ac-article-surface)}.ac-article-rail-controls button:disabled{opacity:.3;cursor:default}.ac-article-rail :is(button,a):focus-visible{outline:2px solid var(--ac-article-accent);outline-offset:3px}.ac-article-rail-viewport{overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;scrollbar-width:thin;scrollbar-color:var(--ac-article-line) transparent;padding:4px 4px 15px;margin:0 -4px;overscroll-behavior-x:contain}.ac-article-rail-track{position:relative;display:flex;align-items:stretch;gap:19px;width:max-content;min-width:100%;list-style:none;margin:0;padding:0}.ac-article-rail-item{flex:0 0 clamp(220px,62cqw,380px);width:clamp(220px,62cqw,380px);min-width:0;scroll-snap-align:start;scroll-snap-stop:normal}.ac-article-rail-item article{height:100%}.ac-article-rail-link{display:block;height:100%;color:inherit;text-decoration:none}.ac-article-rail-media{position:relative;aspect-ratio:4/3;overflow:hidden;background:var(--ac-article-line);border-radius:3px;pointer-events:none}.ac-article-rail-media>img,.ac-article-rail-media>video{display:block;width:100%;height:100%;object-fit:cover;transition:transform .45s cubic-bezier(.2,.7,.2,1)}.ac-article-rail-link-arrow{position:absolute;right:13px;bottom:13px;display:grid;place-items:center;width:34px;height:34px;background:var(--ac-article-surface);color:var(--ac-article-ink);border-radius:50%;font-size:20px;transform:translateY(6px);opacity:0;transition:opacity .2s,transform .2s}.ac-article-rail-link:is(:hover,:focus-visible) .ac-article-rail-link-arrow{transform:translateY(0);opacity:1}.ac-article-rail-link:is(:hover,:focus-visible) .ac-article-rail-media>img{transform:scale(1.035)}.ac-article-rail-meta{display:flex;gap:8px;align-items:baseline;justify-content:space-between;margin:16px 0 10px;color:var(--ac-article-muted);font-size:9px;line-height:1.5;letter-spacing:.035em}.ac-article-rail-meta>span:first-child{text-transform:uppercase}.ac-article-rail-meta>span:last-child{text-align:right}.ac-article-rail-link h3{margin:0;font-size:clamp(20px,3.8cqw,28px);font-weight:500;letter-spacing:-.04em;line-height:1.2;text-wrap:pretty}.ac-article-rail-link h3>span{background:linear-gradient(currentColor,currentColor) left bottom/0 1px no-repeat;transition:background-size .25s}.ac-article-rail-link:is(:hover,:focus-visible) h3>span{background-size:100% 1px}
@container(max-width:350px){.ac-article-rail-header{align-items:center;gap:12px}.ac-article-rail-header h2{font-size:27px}.ac-article-rail-controls{gap:5px}.ac-article-rail-controls button{width:44px;height:44px}.ac-article-rail-item{flex-basis:82cqw;width:82cqw;min-width:190px}}
@media(prefers-reduced-motion:reduce){.ac-article-rail-controls button,.ac-article-rail-link-arrow,.ac-article-rail-link h3>span,.ac-article-rail-media>img,.ac-article-rail-media>video{transition:none}}

/* Neutral surfaces follow an explicit page theme; artwork and accents keep their palette. */
:where([data-theme="light"]) .ac-article-rail {
  --ac-article-theme-ink: #202722;
  --ac-article-theme-line: #d7ded4;
  --ac-article-theme-muted: #687269;
  --ac-article-theme-surface: #fafbf8;
  color-scheme: light;
}
:where([data-theme="dark"], .dark) .ac-article-rail {
  --ac-article-theme-ink: #edf2eb;
  --ac-article-theme-line: #3d483e;
  --ac-article-theme-muted: #a7b3a3;
  --ac-article-theme-surface: #191e1b;
  color-scheme: dark;
}
:where([data-theme="dark"], .dark) .ac-article-rail :is(button, a):focus-visible { outline-color: var(--ac-article-ink); }
